const nx=NX[b.t],nl=b.lv+1;h+='<div class="acts"><button data-a="rotb">↻ Tourner</button><button data-a="copy">Copier</button>'+(nx&&U.b.has(nx)?`<button class="pri" data-a="up">→ Mk${nx.slice(-1)} · ${BD[nx].cost-Math.floor(d.cost/2)} $</button>`:'')+((d.m||d.rt)&&nl<=5&&lvOK(nl)?`<button class="pri" data-a="lvl">Niveau ${nl} · ${lvCost(b).toLocaleString(LOC)} $</button>`:'')+(STORE[b.t]?'<button data-a="empty">Vider</button>':'')+(b.t=='dronest'?`<button class="${b.mode!='recv'?'pri':''}" data-a="dsend">Envoi</button><button class="${b.mode=='recv'?'pri':''}" data-a="drecv">Réception</button>`:'')+`<button class="dan" data-a="del">Démolir +${(d.cost*(b.lv||1)).toLocaleString(LOC)} $</button></div>`;
