function updInsp(){const b=sel;if(!b||!$('led'))return;const s=status(b),d=BD[b.t],r=R[b.rec];$('led').style.color=LED[s];
let t=d.m&&!r?'Choisis une recette':LT[s];if(BELTS[b.t])t=beltCount(b)?'Transporte '+beltCount(b)+' objet'+(beltCount(b)>1?'s':'')+' : '+[...new Set(b.q.map(e=>IT[e.it][0]))].join(', '):'Vide · orienté '+DS[b.d];else if(CARRY[b.t])t=b.item?'Transporte : '+IT[b.item][0]:'Vide · orienté '+DS[b.d];else if(b.t=='seller')t='Vend au cours du marché';
else if(b.t=='accu')t='Charge : '+Math.round((b.ch||0)/ACAP*100)+' %'+(b.mw?' · rend '+b.mw+' MW':'');
else if(b.t=='dronest')t=b.mode=='recv'?'Réception : les drones livrent ici, la sortie est devant':'Envoi : '+((b.dq||[]).length)+' en attente'+(b.fl?' · drone en vol':'')+(L.some(o=>o.t=='dronest'&&o.mode=='recv')?'':' · aucune station en Réception');
else if(b.t=='recycler')t=b.cur?'Démonte : '+IT[b.cur][0]:'Envoie-lui des objets fabriqués';
else if(b.t=='wpump')t='60 eaux par minute';
else if(b.t=='gen_steam')t=(b.mw?'Produit '+b.mw+' MW':'À l’arrêt')+' · eau '+Math.floor(b.wat||0)+' · charbon '+((b.fq||[]).length);
if((d.m&&r||d.rt)&&b.ua!=null){const pc=Math.round(b.ua*100);t+=' · active à '+pc+' %';if(pc<85&&b.why)t+=' · '+(b.why=='out'?'sortie bloquée':b.why=='pow'?'courant faible':'manque : '+(IT[b.why]?IT[b.why][0]:b.why))}
$('stx').textContent=t;
let p=0,rate=0;if(d.rt){p=(d.rt-Math.max(0,b.cd))/d.rt;rate=okRes(b)?Math.round(120/d.rt):0;const so=$('so');if(so)so.textContent=b.out.length+'/3'}
else if(d.m&&r){p=b.busy?(r.t-b.pr)/r.t:0;rate=Math.round(120/r.t*LVS[b.lv-1]);for(const k in r.in){const e=$('si-'+k);if(e)e.textContent=(b.buf[k]||0)+'/'+r.in[k]*2}const so=$('so');if(so)so.textContent=b.out.length+'/4'}
const gg=$('gg');if(gg){gg.style.strokeDashoffset=75.4*(1-Math.max(0,Math.min(1,p)));$('gt').textContent=s=='g'?rate:'0'}
const si=$('silo');if(si)si.innerHTML=b.tot?Object.keys(b.st2).filter(k=>b.st2[k]).map(k=>`<div class="slot"><div>${ic(k)}</div><small>${b.st2[k]}</small></div>`).join('')+`<span class="hint m">${b.tot}/${BD[b.t].cap}</span>`:'<span class="hint">Silo vide</span>';
const gv=$('genv');if(gv)gv.innerHTML=`<div class="slot out"><div>${svg('bolt')}</div><small>${b.mw||0} MW</small></div>`+(b.fq?`<div class="slot"><div>${b.fq.length?ic(b.fq[0]):''}</div><small>${b.fq.length}/6</small></div>`:'');
const gr=$('gridr');if(gr){gr.textContent=Math.round(GRID.r*100)+' %';gr.style.color=GRID.r<1?'var(--rd)':'var(--gn)'}
const pv=$('padv');if(pv)pv.innerHTML=b.ct?`<div class="slot out"><div>${ic(b.ct.item)}</div><small>${b.ct.got}/${b.ct.n}</small></div><span class="hint">+${b.ct.reward} $ à la livraison</span>`:'<span class="hint">En attente d’un vaisseau…</span>'}
function radar(g,w){const c=w/2,a=time/1400;g.save();g.translate(c,c);g.strokeStyle='rgba(255,148,66,.16)';g.lineWidth=D;for(const r of[.25,.5,.75]){g.beginPath();g.arc(0,0,c*r,0,7);g.stroke()}g.beginPath();g.moveTo(-c,0);g.lineTo(c,0);g.moveTo(0,-c);g.lineTo(0,c);g.stroke();
for(let i=0;i<26;i++){g.fillStyle=`rgba(255,148,66,${(.2*(1-i/26)).toFixed(3)})`;g.beginPath();g.moveTo(0,0);g.arc(0,0,c*1.42,a-i*.04,a-(i+1)*.04,true);g.closePath();g.fill()}g.restore()}
